import { ensureElement } from '../../utils/utils';
import { Product } from './common/Product';
export class ProductInBasket extends Product {
    constructor(container, events) {
        super(container, events);
        this.container = container;
        this.basketButton = ensureElement('.basket__item-delete', this.container);
        this.basketButton.addEventListener('click', () => this.events.emit('product:delete', { productId: this.id }));
    }
}
