export class ProductListData {
    constructor(events) {
        this.events = events;
    }
    getProduct(productId) {
        return this._products.find((item) => item.id === productId);
    }
    set items(products) {
        this._products = products;
        this.events.emit('products: set');
    }
    get items() {
        return this._products;
    }
}
