import { Form } from './common/Form';
import { ensureAllElements } from '../../utils/utils';
export class OrderDeliveryForm extends Form {
    constructor(container, events) {
        super(container, events);
        this.paymentBtns = ensureAllElements('.button_alt', this.container);
        this.paymentBtns.forEach((button) => {
            button.addEventListener('click', () => {
                this.payment = button.name;
                this.onInputChange('payment', button.name);
            });
        });
    }
    set payment(value) {
        this.paymentBtns.forEach((button) => {
            this.toggleClass(button, 'button_alt-active', button.name === value);
        });
    }
    set address(value) {
        this.container.elements.namedItem('address').value =
            value;
    }
}
export class OrderContactForm extends Form {
    constructor(container, events) {
        super(container, events);
    }
    set phone(value) {
        this.container.elements.namedItem('phone').value =
            value;
    }
    set email(value) {
        this.container.elements.namedItem('email').value =
            value;
    }
}
